  var origin=new IntVec3(10,0,10);var threats=new List<IntVec3>{new IntVec3(9,0,10),new IntVec3(10,0,11),new IntVec3(11,0,10)};var candidates=new List<IntVec3>();for(int x=5;x<=15;x++)for(int z=5;z<=15;z++)candidates.Add(new IntVec3(x,0,z));
