  Check(!AzureReversal.Plan(origin,threats,candidates,open,(a,b,r)=>false,out leap,out end),"Planner bypassed blocked leap path");Check(!AzureReversal.Plan(origin,threats,candidates,open,(a,b,r)=>!r,out leap,out end),"Planner bypassed blocked rush path");
  Check(AzureReversal.Plan(origin,new List<IntVec3>{threats[0],threats[1]},candidates,open,(a,b,r)=>true,out leap,out end),"Two pressuring enemies should unlock reversal");Check(!AzureReversal.Plan(origin,new List<IntVec3>{threats[0]},candidates,open,(a,b,r)=>true,out leap,out end),"One enemy should not unlock reversal");Check(!AzureReversal.Plan(origin,threats,new[]{origin,new IntVec3(30,0,10)},open,(a,b,r)=>true,out leap,out end),"Planner accepted out-of-range escape");
