  var aPos=driver.VisualPosition(100);var mid=driver.VisualPosition(112);var bPos=driver.VisualPosition(124);Check(aPos.x==10.5f&&bPos.x==4.5f&&mid.x==7.5f&&Math.Abs(mid.z-11.15f)<.001,"Leap render does not follow the planned arc");Set(driver,"phase",2);Set(driver,"phaseStart",200);Check(Math.Abs(driver.VisualPosition(209).x-10f)<.001,"Rush render does not interpolate both endpoints");
  var toils=new List<Toil>((IEnumerable<Toil>)typeof(JobDriver_AzureReversal).GetMethod("MakeNewToils",F).Invoke(driver,null));Check(toils.Count==4&&toils[0].defaultDuration==24&&toils[2].defaultDuration==18&&toils[0].handlingFacing&&toils[2].handlingFacing&&toils[0].tickAction!=null&&toils[2].tickAction!=null,"Native movement toils missing duration, facing or collision rechecks");
  pawn.jobs=Empty<Pawn_JobTracker>();pawn.jobs.curJob=new Job{def=new JobDef{defName=AzureReversal.JobName}};Check(AzureReversal.Busy(pawn)&&ElementalAnimationBridge.Controlled(pawn),"Rush does not gate other skills/transformations/counters");pawn.jobs.curJob.def.defName="Wait_Combat";Check(!AzureReversal.Busy(pawn),"Busy gate leaked after job replacement");
