  Console.WriteLine("PASS: fifth ability adds independently to an older Azure component set and preserves existing cooldown-list identity, automation and its own saved cooldown on repeat upgrades.");
  var drawData=new DrawData();Set(drawData,"dataSouth",(DrawData.RotationalData?)new DrawData.RotationalData{offset=new Vector3(.0645f,0,0)});Check(drawData.OffsetForRot(Rot4.South).x==.0645f&&drawData.OffsetForRot(Rot4.North).x==0&&drawData.OffsetForRot(Rot4.East).x==0&&drawData.OffsetForRot(Rot4.West).x==0,"Native directional alignment offset leaked to other facings");
  var reversal=new HediffComp_AzureReversal{readyAt=65432};var payload=new ReversalSaveCase{ability=reversal,driver=driver};Set(driver,"phase",2);Set(driver,"phaseStart",54321);Set(driver,"hit",true);
  string file=Path.Combine(Path.GetTempPath(),"ReversalTest_"+Guid.NewGuid().ToString("N")+".xml");Scribe.saver.InitSaving(file,"ReversalTest");Scribe_Deep.Look(ref payload,"state");Scribe.saver.FinalizeSaving();var xml=new System.Xml.XmlDocument();xml.Load(file);
  Check(xml.SelectSingleNode("ReversalTest/state/EH_azureReversalReadyAt").InnerText=="65432"&&xml.SelectSingleNode("ReversalTest/state/driver/EH_reversalPhase").InnerText=="2"&&xml.SelectSingleNode("ReversalTest/state/driver/EH_reversalHit").InnerText=="True","Native save output lost cooldown, movement phase or one-hit guard");File.Delete(file);
  Console.WriteLine("PASS: front-only native DrawData offset and native Scribe save output for separate fifth-slot cooldown, movement phase/start and one-hit guard. Native load/live movement not exercised.");
 }
